(356, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 1, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 1, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «ATM-2025» в городе Дубай (ОАЭ)\", \"number\": \"119-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXYZTE21PNFR3VK32CD6APJG.pdf\", \"issued_at\": \"2025-04-23 00:00:00\", \"created_at\": \"2026-07-20 10:26:14\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «ATM-2025», проходящей 28 апреля — 1 мая 2025 г. в Дубае (ОАЭ). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). ГУП «Milliy PR-markazi» поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы и привлечь к выставке субъектов предпринимательства в сфере туризма.\", \"document_key\": \"0BPyOYrqPfTylLEqd2pi\"}}', NULL, '2026-07-20 05:26:14', '2026-07-20 05:26:14'),
(357, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 2, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 2, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «FITUR 2025» в городе Мадрид (Испания)\", \"number\": \"06-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXYZYSWY025CR4PVAEZCBQ7V.pdf\", \"issued_at\": \"2025-01-06 00:00:00\", \"created_at\": \"2026-07-20 10:28:38\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «FITUR 2025», проходящей 22–26 января 2025 г. в Мадриде (Испания). Утверждается список ответственных лиц/участников делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Ответственные члены делегации направляются в командировку в Мадрид 20–27 января, остальные участники — 21–27 января 2025 г. ГУП «Milliy PR-markazi» поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы, привлечь к выставке субъектов предпринимательства в сфере туризма, покрыть расходы, связанные с участием своих сотрудников (согласно приложению 2), и в течение 7 дней после завершения выставки представить Комитету отчёт о принятых мерах.\", \"document_key\": \"rMsWpYus1f9VCvJlrsLi\"}}', NULL, '2026-07-20 05:28:38', '2026-07-20 05:28:38'),
(358, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 3, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 3, \"scope\": \"external\", \"title\": \"О проведении «GITF» международной туристической выставки в городе Гуанчжоу (КНР) и организации «роуд-шоу» в рамках «Года туризма Узбекистана в Китае»\", \"number\": \"142-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ01XSDT6VGPH94AHBDK8W9.pdf\", \"issued_at\": \"2025-05-12 00:00:00\", \"created_at\": \"2026-07-20 10:30:20\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз, изданный во исполнение поручения Кабинета Министров РУз от 27 января 2025 г. № 22/33-65, об обеспечении участия в международной туристической выставке «GITF», проходящей 13–22 мая 2025 г. в Гуанчжоу (КНР), а также организации «роуд-шоу» мероприятий в городах Пекин, Чжэнчжоу и Синдао в рамках «Года туризма Узбекистана в Китае». Утверждается список членов делегации, направляемой в КНР (приложение 1), и смета расходов на организацию мероприятий (приложение 2). К руководству и исполнению принимаются поручения Кабинета Министров от 27 января 2025 г. № 22/33-65 и от 25 марта 2025 г. № 22/1-2006. Ответственным по вопросам повышения эффективности духовно-просветительской работы и соблюдения законодательства о государственном языке назначен советник Раиса Ф. Додиев.\", \"document_key\": \"ohpQ9Shb3tGOewoKXGSH\"}}', NULL, '2026-07-20 05:30:20', '2026-07-20 05:30:20'),
(359, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 4, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 4, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «IFTM Top Resa-2025» и Каннском фестивале в городе Париж (Франция)\", \"number\": \"292-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ03KXC8G7VPEGQ7NF0ZJ5F.pdf\", \"issued_at\": \"2025-08-26 00:00:00\", \"created_at\": \"2026-07-20 10:31:15\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз, изданный во исполнение поручения Кабинета Министров РУз от 27 января 2025 г. № 22/33-65 и поручения Комитета от 13 мая 2025 г. № 388, об обеспечении участия узбекистанских туристических компаний с национальным стендом Узбекистана в международной туристической выставке «IFTM Top Resa-2025», проходящей 23–25 сентября 2025 г. в Париже (Франция), а также участия делегации Узбекистана в Каннском фестивале. Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Члены делегации направляются в командировку в Париж и Канны на 22–26 сентября 2025 г. ГУП «Milliy PR-markazi» поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы и видеоролики, привлечь к выставке субъектов предпринимательства в сфере туризма, а также покрыть связанные расходы согласно приложению 2 в установленном порядке.\", \"document_key\": \"gxiI9ZHcmhOSKu01WVDS\"}}', NULL, '2026-07-20 05:31:15', '2026-07-20 05:31:15'),
(360, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 5, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 5, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «ITB Berlin 2025» в городе Берлин (ФРГ)\", \"number\": \"34-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0ANC8GE8EC9T4G51KT7ZC.pdf\", \"issued_at\": \"2025-07-07 00:00:00\", \"created_at\": \"2026-07-20 10:35:06\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «ITB Berlin 2025», проходящей 4–6 марта 2025 г. в Берлине (ФРГ). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Ответственный за организационные вопросы делегации (Шаипов) направляется в командировку в Берлин 2–7 марта 2025 г. ГУП «Milliy PR-markazi» поручается организовать национальный стенд Узбекистана и продвигать туристический потенциал страны через раздаточные материалы.\", \"document_key\": \"07cwjpZUorwLVQbGaJws\"}}', NULL, '2026-07-20 05:35:06', '2026-07-20 05:35:06'),
(361, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 6, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 6, \"scope\": \"external\", \"title\": \"Об участии с национальным стендом Узбекистана на международных туристических ярмарках\", \"number\": \"74-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0CJS4HTAR5V3SVG0TNSXX.pdf\", \"issued_at\": \"2025-03-13 00:00:00\", \"created_at\": \"2026-07-20 10:36:09\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз о заблаговременной подготовке к участию в международных туристических ярмарках 2025 года с национальным стендом Узбекистана. Утверждается перечень международных туристических ярмарок, в которых планируется участие Комитета в 2025 году (приложение 1), и расходы на аренду земли/площади и строительство стенда (приложение 2). Управлению финансов и экономики (Махмудов) поручено финансирование расходов согласно приложению 2 за счёт средств внебюджетного фонда поддержки развития туризма при Комитете, с перечислением средств ГУП «Milliy PR-markazi». Отделу комплаенс-контроля, противодействия коррупции и внутреннего аудита (Равшанов) совместно с ГУП «Milliy PR-markazi» поручено координировать вопросы, связанные с арендой земли и строительством стендов на ярмарках. ГУП «Milliy PR-markazi» (Муродуллаев) поручено обеспечить участие с национальным стендом на международных туристических ярмарках согласно приложению 2 и представлять Комитету отчёт по итогам каждой ярмарки, а также в течение недели после каждой ярмарки представлять в Управление финансов и экономики финансовый отчёт по понесённым расходам и меры по возврату сэкономленных средств. Отделу информационной службы (Асилходжаева) поручено обеспечить широкое освещение хода выставки на официальных веб-сайтах и в социальных сетях Комитета и ОАВ.\", \"document_key\": \"HrbrEqnkzT1KTwsyrrpL\"}}', NULL, '2026-07-20 05:36:09', '2026-07-20 05:36:09'),
(362, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 7, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 7, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «Matta Fair 2025» в городе Куала-Лумпур (Малайзия)\", \"number\": \"301-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0K6Z44QE5DRT9BM7QSEAB.pdf\", \"issued_at\": \"2025-08-28 00:00:00\", \"created_at\": \"2026-07-20 10:39:46\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «Matta Fair 2025», проходящей 5–7 сентября 2025 г. в Куала-Лумпуре (Малайзия). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Члены делегации направляются в командировку в Куала-Лумпур на 4–8 сентября 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать строительство национального стенда Узбекистана и проконтролировать все организационные вопросы, направить своих сотрудников в командировку для подготовки к выставке, привлечь к выставке субъектов предпринимательства в сфере туризма, а также в течение 7 дней после завершения выставки представить Комитету отчёт.\", \"document_key\": \"36LHFDEeY0eEApwNBVNk\"}}', NULL, '2026-07-20 05:39:46', '2026-07-20 05:39:46'),
(363, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 8, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 8, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «MITT 2025» в городе Москва (Российская Федерация)\", \"number\": \"73-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0MRTH2G4CKX8RWM8NP8DF.pdf\", \"issued_at\": \"2025-03-13 00:00:00\", \"created_at\": \"2026-07-20 10:40:37\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «MITT 2025», проходящей 18–20 марта 2025 г. в Москве (РФ). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Ответственный за организационные вопросы делегации (Гафуров) направляется в командировку в Москву 16–21 марта 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы, привлечь к выставке субъектов предпринимательства в сфере туризма, покрыть расходы согласно приложению 2 в установленном порядке (при этом расходы на командировку сотрудников центра осуществляются за счёт собственных средств организации), а также в течение 3 дней после завершения выставки представить Комитету отчёт.\", \"document_key\": \"viA0o56kNP15CiJCXBm6\"}}', NULL, '2026-07-20 05:40:37', '2026-07-20 05:40:37'),
(364, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 9, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 9, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «SATTE 2025» в городе Нью-Дели (Индия)\", \"number\": \"39-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0P307QTVDE307EZ9MX0X2.pdf\", \"issued_at\": \"2025-02-10 00:00:00\", \"created_at\": \"2026-07-20 10:41:21\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «SATTE 2025», проходящей 19–21 февраля 2025 г. в Нью-Дели (Индия). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Ответственные за организационные вопросы члены делегации направляются в командировку в Нью-Дели 18–22 февраля 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы, привлечь к выставке субъектов предпринимательства в сфере туризма, покрыть расходы, связанные с участием своих сотрудников, согласно приложению 2 в установленном порядке, а также в течение 3 дней после завершения выставки представить Комитету отчёт. Управлению финансов и экономики (Махмудов) поручено обеспечить финансирование расходов согласно приложению 2 за счёт средств внебюджетного фонда поддержки развития туризма при Комитете (за исключением командировочных расходов сотрудников «Milliy PR-markazi»).\", \"document_key\": \"Iv5dOOjdvLeauYQKbyIz\"}}', NULL, '2026-07-20 05:41:21', '2026-07-20 05:41:21'),
(365, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 10, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 10, \"scope\": \"external\", \"title\": \"О «SCITE Sichuan 2025» международной туристической выставке в провинции Сычуань (КНР) и организации «роуд-шоу» в рамках «Года туризма Узбекистана в Китае»\", \"number\": \"110-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0QPZY9ST0F74CRERE4GDE.pdf\", \"issued_at\": \"2025-04-18 00:00:00\", \"created_at\": \"2026-07-20 10:42:14\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз, изданный во исполнение поручения Кабинета Министров РУз от 27 января 2025 г. № 22/33-65, об обеспечении участия в международной туристической выставке «SCITE Sichuan 2025», проходящей 24 апреля – 1 мая 2025 г. в провинции Сычуань (КНР), а также организации «роуд-шоу» мероприятий в городах Чанша и Чунцин в рамках «Года туризма Узбекистана в Китае». К руководству и исполнению принимаются поручения Кабинета Министров от 27 января 2025 г. № 22/33-65 и от 25 марта 2025 г. № 22/1-2006. Утверждается список членов делегации, направляемой в КНР (приложение 1), и смета расходов на организацию мероприятий (приложение 2). Советнику по вопросам повышения эффективности духовно-просветительской работы и соблюдения законодательства о государственном языке Ф. Додиеву поручено координировать организационные вопросы мероприятия. УП «Ipak yo\'li ofisi» (Валиджанов) поручено проработать организационные вопросы, связанные с визитом делегации, и разработать проект маршрута, освещающего туристический потенциал Узбекистана.\", \"document_key\": \"IRti42eZ4JXEjGtMpFen\"}}', NULL, '2026-07-20 05:42:14', '2026-07-20 05:42:14'),
(366, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 11, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 11, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «SITF 2025» в городе Сеул (Республика Корея)\", \"number\": \"166-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0V2Q6J252SA5PRJ5M6WEM.pdf\", \"issued_at\": \"2025-05-27 00:00:00\", \"created_at\": \"2026-07-20 10:44:04\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «SITF 2025», проходящей 5–8 июня 2025 г. в Сеуле (Республика Корея), а также в бизнес-форуме «Туристический потенциал Узбекистана», который состоится 9 июня в здании посольства Узбекистана в Корее. Утверждается список сотрудников Комитета и ГУП «Milliy PR-markazi», участвующих в выставке и форуме (приложение 1), и смета расходов, связанных с участием (приложение 2). Ответственные за организационные вопросы делегации направляются в командировку в Сеул 4–10 июня 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать национальный стенд Узбекистана и продвигать туристический потенциал страны через раздаточные материалы.\", \"document_key\": \"9lc0gqYodHVl53fxcL8h\"}}', NULL, '2026-07-20 05:44:04', '2026-07-20 05:44:04'),
(367, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 12, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 12, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «TT Warsaw 2025» в городе Варшава (Польша)\", \"number\": \"306-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0X6B7EX1B3H9V3MKXAAKR.pdf\", \"issued_at\": \"2025-09-03 00:00:00\", \"created_at\": \"2026-07-20 10:45:13\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз об обеспечении участия в международной туристической выставке «TT Warsaw 2025», проходящей 10–12 октября 2025 г. в Варшаве (Польша). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Члены делегации направляются в командировку в Варшаву на 9–13 октября 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать строительство национального стенда Узбекистана и проконтролировать все организационные вопросы, направить своих сотрудников в командировку для подготовки к выставке, привлечь к выставке субъектов предпринимательства в сфере туризма, а также в течение 3 дней после завершения выставки представить Комитету отчёт. Управлению финансов и экономики (Махмудов) поручено финансирование командировочных расходов сотрудников ГУП «Milliy PR-markazi», ОАВ и участников культурной программы за счёт средств внебюджетного фонда поддержки развития туризма при Комитете.\", \"document_key\": \"dPZziWUCv6VzxStwKWzD\"}}', NULL, '2026-07-20 05:45:13', '2026-07-20 05:45:13'),
(368, 'Model', 'Order Created by Sardor Abdusattorov', 'App\\Models\\Order', 13, 'Created', 'App\\Models\\User', 1, '{\"attributes\": {\"id\": 13, \"scope\": \"external\", \"title\": \"Об участии в международной туристической выставке «World Travel Market» в городе Лондон (Великобритания)\", \"number\": \"359-AF\", \"status\": true, \"file_path\": \"uploads/files/orders/2026/07/01KXZ0YK37YNWJ76XD4S1YHNZF.pdf\", \"issued_at\": \"2025-10-21 00:00:00\", \"created_at\": \"2026-07-20 10:45:59\", \"created_by\": 1, \"description\": \"Приказ Комитета по туризму при Министерстве экологии, охраны окружающей среды и изменения климата РУз, изданный во исполнение поручения Кабинета Министров РУз от 27 января 2025 г. № 22/33-65, об обеспечении участия делегации Узбекистана в международной туристической выставке «World Travel Market», проходящей 4–6 ноября 2025 г. в Лондоне (Великобритания). Утверждается список членов делегации (приложение 1) и смета расходов, связанных с участием (приложение 2). Члены делегации направляются в командировку в Лондон на 2–7 ноября 2025 г. ГУП «Milliy PR-markazi» (Муродуллаев) поручается организовать национальный стенд Узбекистана, продвигать туристический потенциал страны через раздаточные материалы и видеоролики, привлечь к выставке субъектов предпринимательства в сфере туризма, а также организовать зону «Uzbekistan VR» с необходимым оборудованием.\", \"document_key\": \"JiENyItskP8QvX8HYuUd\"}}', NULL, '2026-07-20 05:45:59', '2026-07-20 05:45:59'),
