INSERT INTO `contract_types` (`id`, `title`, `description`, `direction`, `counterparty_kind`, `sort`, `status`, `created_at`, `updated_at`) VALUES
(1, '{\"en\": \"Exhibition space rental\", \"ru\": \"Аренда площади\", \"uz\": \"Maydon ijarasi\"}', '{\"en\": \"Renting exhibition space from the organiser or via an intermediary\", \"ru\": \"Аренда выставочной площади у организатора или через посредника\", \"uz\": \"Tashkilotchidan yoki vositachi orqali ko\'rgazma maydonini ijaraga olish\"}', 'expense', 'contact', 1, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(2, '{\"en\": \"Stand construction\", \"ru\": \"Застройка стенда\", \"uz\": \"Stend qurish\"}', '{\"en\": \"Turnkey exhibition stand: installation and dismantling to approved sketches\", \"ru\": \"Готовый выставочный стенд: монтаж и демонтаж по утверждённым эскизам\", \"uz\": \"Tayyor ko\'rgazma stendi: tasdiqlangan eskizlar bo\'yicha montaj va demontaj\"}', 'expense', 'contact', 2, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(3, '{\"en\": \"Services\", \"ru\": \"Оказание услуг\", \"uz\": \"Xizmat ko\'rsatish\"}', '{\"en\": \"Services to participants: organising participation on the national stand\", \"ru\": \"Услуги участникам: организация участия на национальном стенде\", \"uz\": \"Ishtirokchilarga xizmatlar: milliy stendda ishtirokni tashkil etish\"}', 'income', 'contact', 5, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(4, '{\"en\": \"Contractor services\", \"ru\": \"Услуги подрядчика\", \"uz\": \"Pudratchi xizmatlari\"}', '{\"en\": \"Services we pay for: roadshows, transport, equipment\", \"ru\": \"Услуги, которые оплачиваем мы: роудшоу, транспорт, оборудование\", \"uz\": \"Biz to\'laydigan xizmatlar: roudshou, transport, jihozlar\"}', 'expense', 'contact', 3, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(5, '{\"en\": \"Agency services\", \"ru\": \"Агентские услуги\", \"uz\": \"Agentlik xizmatlari\"}', '{\"en\": \"Payment facilitation: transferring funds to the organiser via an agent\", \"ru\": \"Содействие в расчётах: транзит платежа организатору через агента\", \"uz\": \"Hisob-kitoblarda ko\'maklashish: to\'lovni agent orqali tashkilotchiga o\'tkazish\"}', 'expense', 'contact', 4, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(6, '{\"en\": \"Participant fee\", \"ru\": \"Взнос участника\", \"uz\": \"Ishtirokchi badali\"}', '{\"en\": \"Tour operator\'s fee for participating on the national stand\", \"ru\": \"Взнос туроператора за участие в выставке на национальном стенде\", \"uz\": \"Turoperatorning milliy stendda ko\'rgazmada ishtirok etish badali\"}', 'income', 'contact', 6, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09'),
(7, '{\"en\": \"Sponsorship\", \"ru\": \"Спонсорство\", \"uz\": \"Homiylik\"}', '{\"en\": \"Sponsor contribution to a project (e.g. Uzbekistan Airways)\", \"ru\": \"Спонсорский вклад в проект (например, Uzbekistan Airways)\", \"uz\": \"Loyihaga homiylik hissasi (masalan, Uzbekistan Airways)\"}', 'income', 'sponsor', 7, 1, '2026-07-20 05:24:09', '2026-07-20 05:24:09');
